[Form]
public class METOrderExtractScreen extends FormRun
{
    METOrderExtractScreenParameters     metOrderExtractScreenParameters;
    METorderExtractScreenProcessor      metOrderExtractScreenProcessor;

    [FormObservable]
    Volume                              totalVolume;

}

/// <summary>
/// Calculates total pallets.
/// </summary>
/// <returns>pallets</returns>
public display Integer totalPallets()
{
    Integer     pallets; 
    if (WHSParameters::find().METPalletVolume > 0)
    {
        pallets =  any2Int((totalVolume/WHSParameters::find().METPalletVolume));
    }
    return pallets;
}

    /// <summary>
    /// Populates the <c>METOrderExtractScreenTmp</c> table.
    /// </summary>
    public void populateOrders()
    {
        delete_from METOrderExtractScreenTmpDS;

        if (this.args().parmObject() == null)
        {
            metOrderExtractScreenParameters = METOrderExtractScreenParameters::construct();
        }
        else
        {
            metOrderExtractScreenParameters = this.args().parmObject() as METOrderExtractScreenParameters;
        }

        metOrderExtractScreenParameters.loadLastValue(formStr(METOrderExtractScreen));

        metOrderExtractScreenProcessor = METOrderExtractScreenProcessor::construct(METOrderExtractScreenTmpDS, metOrderExtractScreenParameters);

        totalVolume = metOrderExtractScreenProcessor.parmTotalVolume();

        SalesTable_ds.executeQuery();

    }

/// <summary>
/// Form refresh logic.
/// </summary>
private void refresh()
{
    element.populateOrders();
}

    /// <summary>
    /// Form initialise
    /// </summary>
    public void init()
    {
        super();

        OrderExtractGrid.footerShown(true);
    }

